{
  "items": [
    {
      "name": "Int.lt_zpow_iff_log_lt",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ}, 1 < b → ∀ {x : ℤ} {r : R}, 0 < r → (r < ↑b ^ x ↔ Int.log b r < x)"
    },
    {
      "name": "Int.self_le_zpow_clog",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ}, 1 < b → ∀ (r : R), r ≤ ↑b ^ Int.clog b r"
    },
    {
      "name": "Int.zpow_log_le_self",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ} {r : R}, 1 < b → 0 < r → ↑b ^ Int.log b r ≤ r"
    },
    {
      "name": "Int.zpow_le_iff_le_log",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ}, 1 < b → ∀ {x : ℤ} {r : R}, 0 < r → (↑b ^ x ≤ r ↔ x ≤ Int.log b r)"
    },
    {
      "name": "Int.lt_zpow_succ_log_self",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ}, 1 < b → ∀ (r : R), r < ↑b ^ (Int.log b r + 1)"
    }
  ]
}
